export const externalEventBlockerResolutionSchema = {
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://catch.app/contracts/embedded/external_event_blocker_resolution.schema.json",
  "title": "ExternalEventBlockerResolution",
  "description": "One explicit, event-scoped resolution or policy-backed waiver for a governed external-event import blocker.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "blockerCode",
    "outcome",
    "policyGapDecisionId",
    "note"
  ],
  "properties": {
    "blockerCode": {
      "type": "string",
      "enum": [
        "missing_exact_coordinates",
        "missing_end_time",
        "missing_location_detail",
        "requires_event_defaults_policy",
        "requires_owner_safe_copy_review",
        "duplicate_normalized_event_key"
      ]
    },
    "outcome": {
      "type": "string",
      "enum": [
        "resolved",
        "waived"
      ]
    },
    "policyGapDecisionId": {
      "type": [
        "string",
        "null"
      ],
      "minLength": 1,
      "maxLength": 180
    },
    "note": {
      "type": "string",
      "minLength": 1,
      "maxLength": 1000
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "outcome": {
            "const": "waived"
          }
        }
      },
      "then": {
        "properties": {
          "policyGapDecisionId": {
            "type": "string"
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "outcome": {
            "const": "resolved"
          }
        }
      },
      "then": {
        "properties": {
          "policyGapDecisionId": {
            "type": "null"
          }
        }
      }
    }
  ]
};

export const externalEventPublicationReceiptDocumentSchema = {
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://catch.app/contracts/firestore/external_event_publication_receipts.schema.json",
  "title": "ExternalEventPublicationReceiptDocument",
  "description": "Immutable idempotency and audit receipt for a dry-run or applied external-event publication/takedown action.",
  "type": "object",
  "additionalProperties": false,
  "x-firestore-collection": "externalEventPublicationReceipts",
  "x-firestore-path": "externalEventPublicationReceipts/{receiptId}",
  "x-document-id-field": "receiptId",
  "x-owner": "adminPublishExternalEvent and adminTakedownExternalEvent callables",
  "required": [
    "schemaVersion",
    "receiptId",
    "idempotencyKey",
    "inputHash",
    "action",
    "executionMode",
    "outcome",
    "eventId",
    "targetPath",
    "sourceActionId",
    "externalLinkCount",
    "reviewNote",
    "actorUid",
    "createdAt"
  ],
  "properties": {
    "schemaVersion": {
      "type": "integer",
      "const": 1
    },
    "receiptId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 180
    },
    "idempotencyKey": {
      "type": "string",
      "minLength": 8,
      "maxLength": 180
    },
    "inputHash": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    },
    "action": {
      "type": "string",
      "enum": [
        "publish",
        "takedown"
      ]
    },
    "executionMode": {
      "type": "string",
      "enum": [
        "dry_run",
        "apply"
      ]
    },
    "outcome": {
      "type": "string",
      "enum": [
        "would_publish",
        "published",
        "would_remove",
        "removed"
      ]
    },
    "eventId": {
      "type": "string",
      "minLength": 1,
      "maxLength": 180
    },
    "targetPath": {
      "type": "string",
      "pattern": "^externalEvents/[A-Za-z0-9_-]{1,180}$"
    },
    "sourceActionId": {
      "type": [
        "string",
        "null"
      ],
      "maxLength": 240
    },
    "externalLinkCount": {
      "type": "integer",
      "minimum": 0,
      "maximum": 12
    },
    "reviewNote": {
      "type": "string",
      "minLength": 1,
      "maxLength": 1000
    },
    "actorUid": {
      "type": "string",
      "minLength": 1,
      "maxLength": 180
    },
    "createdAt": {
      "type": "object",
      "description": "Serialized Firestore Timestamp fixture shape.",
      "x-firestore-type": "timestamp",
      "additionalProperties": false,
      "required": [
        "_seconds",
        "_nanoseconds"
      ],
      "properties": {
        "_seconds": {
          "type": "integer"
        },
        "_nanoseconds": {
          "type": "integer",
          "minimum": 0,
          "maximum": 999999999
        }
      }
    }
  }
};

